          if en <= ebrm[j]: break L1342
        j = nbrem
      a = (ln(z8t[j]) - ln(z8t[j - 1])) / (ebrm[j] - ebrm[j - 1])
      b = (ln(z8t[j]) * ebrm[j - 1] - ln(z8t[j - 1]) * ebrm[j]) / (ebrm[j - 1] - ebrm[j])
      qin[149, i] = exp(a * en + b) * 2e-24
    # SCHUMANN RUNGE SUM
    sumsr = 0.0
    fdo jk, 77, 103:
      sumsr = sumsr + qin[jk, i]
    # DISS SUM ABOVE IONISATION ENERGY
    sumdisi = 0.0
    fdo jk, 118, 148:
      sumdisi = sumdisi + qin[jk, i]
    # SUM DISS LOW
    sumdisl = 0.0
    fdo jk, 107, 117:
      sumdisl = sumdisl + qin[jk, i]
    # SUM ROT
    sumrot = 0.0
    fdo jk, 1, 48:
      sumrot = sumrot + qin[jk, i]
    # WRITE(6,8747) SUMROT,I,EN
    # 8747 FORMAT(' SUMROT=',D12.4,' I=',I5,' EN=',D12.4)
    # SUMVIB
    sumvib = 0.0
    fdo jk, 49, 54:
      sumvib = sumvib + qin[jk, i]
    sumvib = sumvib + qin[55, i] + qin[56, i] + qin[57, i]
    fdo jk, 60, 72:
      sumvib = sumvib + qin[jk, i]
    # SUM HERZBERG
    sumherz = qin[73, i] + qin[74, i] + qin[75, i]
    # SUM E3SIGMA
    sume3 = qin[104, i] + qin[105, i] + qin[106, i]
    # SUM ION
    sumion = 0.0
    fdo jk, 1, nion:
      sumion = sumion + qion[jk, i]
    # SUM OF EXCITATIONS (NO ROTATIONS)
    sumexc = 0.0
    fdo jk, 49, nin:
      sumexc = sumexc + qin[jk, i]
    sumexc = sumexc + q[4, i]
    q[1, i] = q[2, i] + sumion + sumexc
    # WRITE(6,889) EN,Q(2,I),SUMEXC,SUMION,Q(1,I),Q(4,I),I
    # 889 FORMAT(' EN=',D12.4,' ELAS=',D12.4,' EXC=',D12.4,' ION=',D12.4,
    # /' TOT=',D12.4,' Q4    =',D12.4,' I=',I5)
    # SUMINEL=SUMION+SUMEXC
    # WRITE(6,890) EN,SUMION,SUMEXC,SUMINEL
    # 890 FORMAT(' EN=',D12.4,' SUMION=',D12.4,' SUMEXC=',D12.4,' SUMINEL=',
    # /D12.4)
  # SAVE COMPUTE TIME
  fdo k, 1, 148:
    j = 149 - k
    if inpt.efinal <= ein[j]: nin = j - 1
  if nin < 52: nin = 52
  # IF(EFINAL.GT.1000.) NIN=149
  return
